CREATE TRIGGER knowledge_pages_fts_delete AFTER DELETE ON knowledge_pages BEGIN INSERT INTO knowledge_pages_fts(knowledge_pages_fts, rowid, title, summary, tags_json, body) VALUES ('delete', old.rowid, old.title, old.summary, old.tags_json, old.body); END;
CREATE TRIGGER knowledge_pages_fts_update AFTER UPDATE ON knowledge_pages BEGIN INSERT INTO knowledge_pages_fts(knowledge_pages_fts, rowid, title, summary, tags_json, body) VALUES ('delete', old.rowid, old.title, old.summary, old.tags_json, old.body); INSERT INTO knowledge_pages_fts(rowid, title, summary, tags_json, body) VALUES (new.rowid, new.title, new.summary, new.tags_json, new.body); END;
