CREATE TABLE runtime_task_custody ( team_id TEXT NOT NULL, task_id TEXT NOT NULL, holder_agent_id TEXT NOT NULL, holder_named_agent_type TEXT, claimed_at TEXT NOT NULL, PRIMARY KEY (team_id, task_id) );
CREATE INDEX idx_runtime_task_custody_holder ON runtime_task_custody(holder_agent_id);
CREATE TABLE schedule_occurrences ( occurrence_id TEXT PRIMARY KEY, schedule_id TEXT NOT NULL, task_id TEXT NOT NULL UNIQUE, team_id TEXT NOT NULL, owner_id TEXT NOT NULL, agent_id TEXT NOT NULL, payload_json TEXT NOT NULL );
CREATE INDEX schedule_occurrence_schedule ON schedule_occurrences(schedule_id);
CREATE TABLE schedule_worker_attempts ( occurrence_id TEXT PRIMARY KEY, schedule_id TEXT NOT NULL, team_id TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, launch_id TEXT, next_attempt_at TEXT, reason TEXT, review_generation INTEGER NOT NULL DEFAULT 0, review_at TEXT );
CREATE TABLE schedule_worker_bindings ( schedule_id TEXT PRIMARY KEY, team_id TEXT NOT NULL, owner_id TEXT NOT NULL, revision INTEGER NOT NULL, payload_json TEXT NOT NULL, pending_schedule_json TEXT, previous_binding_json TEXT );
CREATE INDEX schedule_worker_team ON schedule_worker_bindings(team_id,owner_id);
CREATE TABLE schedule_worker_definition_records ( schedule_id TEXT PRIMARY KEY, team_id TEXT NOT NULL, payload_json TEXT NOT NULL );
CREATE TABLE scheduled_messages ( schedule_id TEXT PRIMARY KEY, payload_json TEXT NOT NULL, schedule_json TEXT, schedule_name TEXT, objective_id TEXT, interval_ms INTEGER, cron_expression TEXT, repeat_count INTEGER, remaining_count INTEGER, next_fire_at TEXT NOT NULL, paused_until TEXT, expires_at_utc TEXT, created_at TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, claim_team_id TEXT, claim_named_agent_type TEXT, claim_agent_id TEXT, owner_canonical_user_id TEXT, claimed_by_agent_id TEXT, claim_token TEXT, claim_expires_at TEXT, claimed_at TEXT, run_permit_json TEXT, run_permit_owner TEXT, run_permit_recheck_at TEXT );
CREATE INDEX idx_scheduled_messages_objective_id ON scheduled_messages(objective_id);
CREATE INDEX idx_scheduled_messages_due_claim ON scheduled_messages( enabled, next_fire_at, claim_team_id, claim_named_agent_type, claim_agent_id, claim_expires_at );
CREATE INDEX idx_scheduled_messages_claim_token ON scheduled_messages(claim_token);
CREATE INDEX idx_scheduled_messages_owner_user ON scheduled_messages(owner_canonical_user_id, next_fire_at);
CREATE TABLE scheduled_run_problems ( team_id TEXT NOT NULL, schedule_id TEXT NOT NULL, failed_task_id TEXT NOT NULL, failed_json TEXT NOT NULL, recovered_json TEXT, PRIMARY KEY (team_id, schedule_id) );
CREATE TABLE sealbox_tenant_mappings ( scope_kind TEXT NOT NULL, owner_id TEXT NOT NULL, tenant_id TEXT NOT NULL UNIQUE, material_id TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, PRIMARY KEY (scope_kind, owner_id) );
CREATE TABLE solution_variation_candidates ( candidate_record_id TEXT PRIMARY KEY, candidate_id TEXT NOT NULL, run_id TEXT NOT NULL, owner_agent_id TEXT NOT NULL, owner_access_scope TEXT NOT NULL, candidate_key TEXT NOT NULL, parent_candidate_key TEXT, candidate_data TEXT NOT NULL, created_at TEXT NOT NULL );
CREATE INDEX idx_solution_variation_candidates_run ON solution_variation_candidates(owner_agent_id, owner_access_scope, run_id, created_at);
CREATE TABLE solution_variation_evaluations ( evaluation_record_id TEXT PRIMARY KEY, evaluation_id TEXT NOT NULL, run_id TEXT NOT NULL, owner_agent_id TEXT NOT NULL, owner_access_scope TEXT NOT NULL, candidate_key TEXT NOT NULL, evaluation_key TEXT NOT NULL, hard_constraints_passed INTEGER NOT NULL, evaluation_data TEXT NOT NULL, created_at TEXT NOT NULL );
CREATE INDEX idx_solution_variation_evaluations_run ON solution_variation_evaluations(owner_agent_id, owner_access_scope, run_id, candidate_key, created_at);
CREATE TABLE solution_variation_runs ( run_record_id TEXT PRIMARY KEY, run_id TEXT NOT NULL, owner_agent_id TEXT NOT NULL, owner_access_scope TEXT NOT NULL, team_id TEXT, source_task_id TEXT NOT NULL, scope_key TEXT NOT NULL, active_scope_key TEXT, plan_id TEXT, plan_step_id TEXT, objective_id TEXT, status TEXT NOT NULL, selected_candidate_key TEXT, revision INTEGER NOT NULL, run_data TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE UNIQUE INDEX idx_solution_variation_active_scope ON solution_variation_runs(active_scope_key);
CREATE INDEX idx_solution_variation_task ON solution_variation_runs(owner_agent_id, owner_access_scope, source_task_id, updated_at DESC);
CREATE INDEX idx_solution_variation_plan ON solution_variation_runs(owner_agent_id, owner_access_scope, plan_id, updated_at DESC);
CREATE TABLE stuck_work_incidents ( incident_id TEXT PRIMARY KEY, team_id TEXT NOT NULL, subject_kind TEXT NOT NULL, subject_id TEXT NOT NULL, payload_json TEXT NOT NULL );
CREATE INDEX stuck_work_team ON stuck_work_incidents(team_id, subject_kind);
CREATE TABLE task_handoff_events ( handoff_event_id TEXT PRIMARY KEY, task_id TEXT NOT NULL, conversation_id TEXT, turn_id TEXT, assigner_id TEXT, assigner_name TEXT, assignee_id TEXT, assignee_name TEXT, handoff_kind TEXT NOT NULL, rationale TEXT, handoff_notes TEXT, created_at TEXT NOT NULL );
CREATE TABLE task_state_snapshots ( snapshot_id TEXT PRIMARY KEY, task_id TEXT NOT NULL, conversation_id TEXT, through_turn_index INTEGER, status TEXT, assignee_id TEXT, priority TEXT, due_at TEXT, active_blockers_json TEXT NOT NULL DEFAULT '[]', active_dependencies_json TEXT NOT NULL DEFAULT '[]', open_questions_json TEXT NOT NULL DEFAULT '[]', next_actions_json TEXT NOT NULL DEFAULT '[]', current_summary TEXT NOT NULL DEFAULT '', state_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL );
CREATE TABLE task_turn_deltas ( delta_id TEXT PRIMARY KEY, task_id TEXT NOT NULL, conversation_id TEXT, turn_id TEXT, turn_index INTEGER, source_kind TEXT NOT NULL, actor_id TEXT, actor_name TEXT, actor_type TEXT, turn_kind TEXT NOT NULL, delta_json TEXT NOT NULL DEFAULT '{}', delta_summary TEXT NOT NULL DEFAULT '', extracted_at TEXT NOT NULL, extractor_version TEXT, batch_id TEXT );
CREATE TABLE tool_setup_runs ( run_id TEXT PRIMARY KEY, team_id TEXT NOT NULL, task_id TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL, updated_at TEXT NOT NULL, payload_json TEXT NOT NULL );
CREATE INDEX tool_setup_runs_task ON tool_setup_runs(team_id, task_id);
CREATE TABLE worker_pool_events ( team_id TEXT NOT NULL, agent_type TEXT NOT NULL, at TEXT NOT NULL, payload_json TEXT NOT NULL );
CREATE INDEX worker_pool_events_time ON worker_pool_events(team_id, agent_type, at);
CREATE TABLE worker_pool_incidents ( incident_id TEXT PRIMARY KEY, team_id TEXT NOT NULL, agent_type TEXT NOT NULL, kind TEXT NOT NULL, opened_at TEXT NOT NULL, closed_at TEXT, payload_json TEXT NOT NULL );
CREATE INDEX worker_pool_incidents_open ON worker_pool_incidents(team_id, agent_type, kind, closed_at);
CREATE TABLE worker_pool_limits ( team_id TEXT NOT NULL, scope TEXT NOT NULL, updated_at TEXT NOT NULL, payload_json TEXT NOT NULL, PRIMARY KEY (team_id, scope) );
CREATE TABLE worker_task_handbacks ( handback_id TEXT PRIMARY KEY, team_id TEXT NOT NULL, task_id TEXT NOT NULL, worker_agent_id TEXT NOT NULL, disposition TEXT NOT NULL, status TEXT NOT NULL, received_at TEXT NOT NULL, updated_at TEXT NOT NULL, payload_json TEXT NOT NULL );
CREATE INDEX worker_task_handbacks_task ON worker_task_handbacks(team_id, task_id, received_at);
CREATE INDEX worker_task_handbacks_status ON worker_task_handbacks(team_id, status, updated_at);
